missing = [t for t, *_ in ENTRIES if t not in ALSO]
assert not missing, f"entries without Also-asked phrases: {missing}"
assert set(ALSO) <= {t for t, *_ in ENTRIES}, "unknown title in ALSO"

ALSO_MARK = "\n\n[Also asked: "


def with_keywords(title: str, content: str) -> str:
    """Content as stored in the database: the passage plus hidden retrieval phrases."""
    return f"{content}{ALSO_MARK}{'; '.join(ALSO[title])}]"
